<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/src/helpers.php'; $user=require_admin();
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $partyId=(int)($_POST['party_id']??0); if ($partyId) { db()->prepare('UPDATE parties SET active=1-active WHERE id=?')->execute([$partyId]); } redirect('parties.php'); }
$mrId=(int)($_GET['mr_id']??0); $area=trim($_GET['area']??''); $type=$_GET['type']??''; $where=[];$params=[];
if($mrId){$where[]='p.mr_id=?';$params[]=$mrId;} if($area!==''){$where[]='p.area LIKE ?';$params[]="%$area%";} if(in_array($type,['doctor','retail'],true)){$where[]='p.type=?';$params[]=$type;}
$sql='SELECT p.*,u.name AS mr_name FROM parties p JOIN users u ON u.id=p.mr_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.active DESC,p.name'; $stmt=db()->prepare($sql);$stmt->execute($params);$parties=$stmt->fetchAll();$mrs=db()->query("SELECT id,name FROM users WHERE role='employee' ORDER BY name")->fetchAll();page_start('All parties',$user);
?>
<a class="button" href="../party_form.php">Add party</a><form method="get" class="card"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>MR<select name="mr_id"><option value="">All MRs</option><?php foreach($mrs as $mr): ?><option value="<?= $mr['id'] ?>" <?= $mrId===$mr['id']?'selected':'' ?>><?= e($mr['name']) ?></option><?php endforeach;?></select></label><label>Area<input name="area" value="<?= e($area) ?>"></label><label>Type<select name="type"><option value="">All types</option><option value="doctor" <?= $type==='doctor'?'selected':'' ?>>Doctor</option><option value="retail" <?= $type==='retail'?'selected':'' ?>>Retail Party</option></select></label><button>Filter</button></form>
<?php foreach($parties as $party): ?><article class="card"><div class="row"><strong><?= e($party['name']) ?></strong><span class="badge <?= $party['active']?'green':'grey' ?>"><?= $party['active']?'Active':'Inactive' ?></span></div><p><?= e($party['mr_name']) ?> · <?= e($party['area']) ?> · <?= e(ucfirst($party['type'])) ?></p><a href="../party_form.php?id=<?= $party['id'] ?>">Edit</a><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="party_id" value="<?= $party['id'] ?>"><button class="secondary"><?= $party['active']?'Deactivate':'Reactivate' ?></button></form></article><?php endforeach; ?>
<?php page_end($user); ?>
